import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
export async function smoke(ctx) {
  const {api,request,check,ids}=ctx;
  const {project}=await api('GET','/projects/'+ids.projectId);
  const path='/projects/'+project.id;
  await check('issue labels preserve project scope name and color',async()=>{
    const label=(await api('POST',path+'/labels',{name:'Acceptance label',color:'#123abc'})).label;
    ids.issueLabelId=label.id;
    const edited=(await api('PATCH','/labels/'+label.id,{name:'Acceptance release'})).label;
    assert.equal(edited.name,'Acceptance release');assert.equal(edited.color,'#123abc');
    const duplicate=await request('POST',path+'/labels',{name:'acceptance release'});
    assert.equal(duplicate.status,409);
  });
  await check('issue fields numbering parent labels edit and HTTP read persist',async()=>{
    const parent=(await api('POST',path+'/issues',{title:'Acceptance parent'})).issue;
    ids.parentIssueId=parent.id;
    const body={title:'Acceptance issue',description:'# Acceptance plan\nShip the release with searchable acceptance details.',statusId:project.statuses[0].id,priority:2,assigneeId:ctx.clients.member.user.id,estimate:5.5,dueDate:'2028-02-29',parentId:parent.id,labelIds:[ids.issueLabelId]};
    const issue=(await api('POST',path+'/issues',body)).issue;
    ids.issueId=issue.id;ids.issueKey=issue.key;
    assert.equal(issue.number,parent.number+1);
    assert.equal(issue.key,project.key+'-'+issue.number);
    for(const field of ['description','statusId','priority','assigneeId','estimate','dueDate','parentId'])assert.equal(issue[field],body[field]);
    assert.equal(issue.labels[0].id,ids.issueLabelId);assert.equal(issue.assignee.id,ctx.clients.member.user.id);
    const changed=(await api('PATCH','/issues/'+issue.id,{title:'Acceptance issue release'})).issue;
    ids.issueExpected={title:changed.title,description:changed.description,estimate:changed.estimate,dueDate:changed.dueDate,parentId:changed.parentId};
    assert.deepEqual((await api('GET','/issues/'+issue.id)).issue,changed);
    const invalid=await request('PATCH','/issues/'+parent.id,{parentId:issue.id});assert.equal(invalid.status,422);assert.ok(invalid.data.error.details.parentId);
    const page=await api('GET',path+'/issues?labelId='+ids.issueLabelId+'&limit=1');assert.equal(page.items[0].id,issue.id);
  });
  await check('member comment safely renders markdown and explicitly mentions owner',async()=>{
    const owner=ctx.clients.owner.user;
    const body='**Ready to ship** <script>unsafe</script> @[Acceptance Owner](user:'+owner.id+')';
    const comment=(await api('POST','/issues/'+ids.issueId+'/comments',{body},'member')).comment;
    ids.commentId=comment.id;ids.mentionCommentId=comment.id;ids.mentionedUserId=owner.id;
    assert.equal(comment.authorId,ctx.clients.member.user.id);
    assert.deepEqual(comment.mentionedUserIds,[owner.id]);
    assert.ok(comment.html.includes('<strong>Ready to ship</strong>'));assert.ok(comment.html.includes('&lt;script&gt;'));assert.equal(comment.html.includes('<script>'),false);
    const comments=await api('GET','/issues/'+ids.issueId+'/comments');assert.equal(comments.items[0].body,body);
  });
  await check('all issue relation kinds preserve directional and symmetric read views',async()=>{
    ids.issueRelationIds=[];ids.relationTargetIds=[];
    for(const kind of ['blocks','duplicates','relates']){
      const target=(await api('POST',path+'/issues',{title:'Acceptance '+kind+' target'})).issue;
      ids.relationTargetIds.push(target.id);
      const relation=(await api('POST','/issues/'+ids.issueId+'/relations',{targetIssueId:target.id,kind})).relation;
      ids.issueRelationIds.push(relation.id);
      const reverse=(await api('GET','/issues/'+target.id+'/relations')).items.find(item=>item.id===relation.id);
      assert.equal(reverse.relatedIssue.id,ids.issueId);assert.equal(reverse.direction,kind==='relates'?'both':'incoming');
      assert.equal(reverse.caption,kind==='blocks'?'blocked by':kind==='duplicates'?'duplicated by':'relates to');
    }
    assert.deepEqual(new Set((await api('GET','/issues/'+ids.issueId+'/relations')).items.map(item=>item.kind)),new Set(['blocks','duplicates','relates']));
  });
  await check('actual issue CLI reads filters labels comments and relation records',async()=>{
    const shown=await ctx.cli(['issue','show',ids.issueId]);assert.equal(shown.issue.title,ids.issueExpected.title);assert.equal(shown.issue.labels[0].id,ids.issueLabelId);
    const list=await ctx.cli(['issue','list',ids.projectId,'--label',ids.issueLabelId,'--query','Acceptance issue release']);assert.ok(list.items.some(issue=>issue.id===ids.issueId));
    const labels=await ctx.cli(['issue','labels',ids.projectId]);assert.ok(labels.items.some(label=>label.id===ids.issueLabelId));
    const comments=await ctx.cli(['issue','comments',ids.issueId]);assert.ok(comments.items.some(comment=>comment.id===ids.commentId));
    const relations=await ctx.cli(['issue','relations',ids.issueId]);assert.equal(relations.items.length,3);
    const comment=(await ctx.cli(['issue','comment',ids.issueId,'--body','CLI acceptance discussion'])).comment;ids.cliCommentId=comment.id;
    const edited=(await ctx.cli(['issue','comment-edit',comment.id,'--body','CLI acceptance discussion edited'])).comment;assert.equal(edited.body,'CLI acceptance discussion edited');
  });
}
export async function restart(ctx) {
  const {api,ids}=ctx;
  await ctx.check('issue fields labels parent comments and relations survive new server process',async()=>{
    const issue=(await api('GET','/issues/'+ids.issueId)).issue;
    for(const [field,value] of Object.entries(ids.issueExpected))assert.equal(issue[field],value);
    assert.ok(issue.labels.some(label=>label.id===ids.issueLabelId));
    const parent=(await api('GET','/issues/'+ids.parentIssueId)).issue;assert.equal(parent.title,'Acceptance parent');
    const comments=(await api('GET','/issues/'+ids.issueId+'/comments')).items;
    const mention=comments.find(comment=>comment.id===ids.commentId);assert.ok(mention);assert.ok(mention.mentionedUserIds.includes(ctx.clients.owner.user.id));assert.ok(mention.html.includes('&lt;script&gt;'));
    assert.ok(comments.some(comment=>comment.id===ids.cliCommentId&&comment.body==='CLI acceptance discussion edited'));
    const relations=(await api('GET','/issues/'+ids.issueId+'/relations')).items;
    assert.deepEqual(new Set(relations.map(relation=>relation.id)),new Set(ids.issueRelationIds));
  });
}
export async function remount(ctx) {
  await ctx.check('saved executable issue CLI reads persisted fields after fresh Workspace mount',async()=>{
    const {issue}=await ctx.cli(['issue','show',ctx.ids.issueId]);
    for(const [field,value] of Object.entries(ctx.ids.issueExpected))assert.equal(issue[field],value);
    assert.ok(issue.labels.some(label=>label.id===ctx.ids.issueLabelId));
    const comments=await ctx.cli(['issue','comments',ctx.ids.issueId]);assert.ok(comments.items.some(comment=>comment.id===ctx.ids.commentId));
  });
}
export async function audit({checks}) {
  const source=await readFile('docs/api-work-issues.md','utf8');
  for(const required of ['issue:write','comment:write','mentionedUserIds','sourceIssueId','blocked by','getIssue(ctx,id)'])assert.ok(source.includes(required),required);
  checks.push({name:'Issue field permission Markdown mention relation CLI and event contracts documented; behavior covered by issue and discussion HTTP/CLI suites',ok:true});
}
